require 'minitest/autorun'
require 'json'
require 'uri'
require 'petstore_client'

class FakeAuthCodeClient
  attr_reader :last_url, :last_body, :urls

  def initialize(responses)
    @responses = responses
    @call_index = 0
    @urls = []
  end

  def send_request(_method, url, _headers, body, **_kwargs)
    @urls << url
    @last_url = url
    @last_body = body
    response = @responses[@call_index] || @responses.last
    @call_index += 1
    Petstore::Client::ApiHttpResponse.new(
      status_code: response[:status],
      body: response[:body].to_json,
      headers: { 'content-type' => 'application/json' }
    )
  end
end

describe Petstore::Client::Auth::OAuth::OAuth2AuthorizationCodeAuthenticator do
  parallelize_me!

  let(:auth) do
    Petstore::Client::Auth::OAuth::OAuth2AuthorizationCodeAuthenticator.new(
      'https://api.example.com',
      'my_client_id',
      'my_client_secret',
      'https://auth.example.com/authorize',
      'https://auth.example.com/token',
      'https://app.example.com/callback',
      %w[read write]
    )
  end

  it 'builds authorization URL with required params' do
    url = auth.build_authorization_url
    _(url).must_include 'https://auth.example.com/authorize?'
    _(url).must_include 'response_type=code'
    _(url).must_include 'client_id=my_client_id'
    _(url).must_include 'redirect_uri='
    _(url).must_include 'scope=read%20write'
  end

  it 'builds authorization URL with state' do
    url = auth.build_authorization_url('csrf_state_123')
    _(url).must_include 'state=csrf_state_123'
  end

  it 'omits an empty state from the authorization URL' do
    url = auth.build_authorization_url('')
    _(url).wont_include 'state'
    _(url).must_equal auth.build_authorization_url
  end

  it 'exchanges code with correct grant type' do
    client = FakeAuthCodeClient.new([
                                      { status: 200, body: { 'access_token' => 'tok_abc', 'refresh_token' => 'ref_xyz', 'expires_in' => 3600 } }
                                    ])
    auth.api_client = client

    auth.exchange_code('auth_code_123')
    _(client.last_body).must_include 'grant_type=authorization_code'
    _(client.last_body).must_include 'code=auth_code_123'
    _(client.last_body).must_include 'client_id=my_client_id'
    _(client.last_body).must_include 'client_secret=my_client_secret'
  end

  it 'includes refresh token on refresh' do
    client = FakeAuthCodeClient.new([
                                      { status: 200, body: { 'access_token' => 'tok_abc', 'refresh_token' => 'ref_xyz', 'expires_in' => -1 } },
                                      { status: 200, body: { 'access_token' => 'tok_refreshed', 'expires_in' => 3600 } }
                                    ])
    auth.api_client = client

    auth.exchange_code('auth_code_123')
    headers = auth.auth_headers
    _(headers['Authorization']).must_equal 'Bearer tok_refreshed'
    _(client.last_body).must_include 'refresh_token=ref_xyz'
  end

  it 'authenticates the client on the refresh grant' do
    client = FakeAuthCodeClient.new([
                                      { status: 200, body: { 'access_token' => 'tok_abc', 'refresh_token' => 'ref_xyz', 'expires_in' => -1 } },
                                      { status: 200, body: { 'access_token' => 'tok_refreshed', 'expires_in' => 3600 } }
                                    ])
    auth.api_client = client

    auth.exchange_code('auth_code_123')
    auth.auth_headers
    _(client.last_body).must_include 'grant_type=refresh_token'
    _(client.last_body).must_include 'client_id=my_client_id'
    _(client.last_body).must_include 'client_secret=my_client_secret'
  end

  it 'surfaces a rejected refresh after exactly one refresh POST' do
    client = FakeAuthCodeClient.new([
                                      { status: 200, body: { 'access_token' => 'tok_abc', 'refresh_token' => 'ref_xyz', 'expires_in' => -1 } },
                                      { status: 400, body: { 'error' => 'invalid_grant' } }
                                    ])
    auth.api_client = client

    auth.exchange_code('auth_code_123')
    err = assert_raises(Petstore::Client::Errors::OAuth2ServerError) { auth.auth_headers }
    _(err.code).must_equal 'invalid_grant'
    _(client.urls.length).must_equal 2
  end

  it 'second exchange_code sends the new code and replaces the session' do
    client = FakeAuthCodeClient.new([
                                      { status: 200, body: { 'access_token' => 'tok_one', 'refresh_token' => 'ref_one', 'expires_in' => 3600 } },
                                      { status: 200, body: { 'access_token' => 'tok_two', 'expires_in' => 3600 } }
                                    ])
    auth.api_client = client

    auth.exchange_code('a')
    auth.exchange_code('b')
    _(client.urls.length).must_equal 2
    _(client.last_body).must_include 'grant_type=authorization_code'
    _(client.last_body).must_include 'code=b'
    _(auth.auth_headers['Authorization']).must_equal 'Bearer tok_two'
  end

  it 'second exchange without a refresh_token drops the old refresh token' do
    client = FakeAuthCodeClient.new([
                                      { status: 200, body: { 'access_token' => 'tok_one', 'refresh_token' => 'ref_one', 'expires_in' => 3600 } },
                                      { status: 200, body: { 'access_token' => 'tok_two', 'expires_in' => 3600 } }
                                    ])
    auth.api_client = client
    manager = auth.instance_variable_get(:@token_manager)

    auth.exchange_code('a')
    _(manager.refresh_token).must_equal 'ref_one'
    auth.exchange_code('b')
    _(manager.refresh_token).must_be_nil
  end

  it 'a failed exchange keeps the previous session' do
    client = FakeAuthCodeClient.new([
                                      { status: 200, body: { 'access_token' => 'tok_one', 'refresh_token' => 'ref_one', 'expires_in' => 3600 } },
                                      { status: 400, body: { 'error' => 'invalid_grant' } }
                                    ])
    auth.api_client = client

    auth.exchange_code('a')
    assert_raises(Petstore::Client::Errors::OAuth2ServerError) { auth.exchange_code('bad') }
    _(auth.auth_headers['Authorization']).must_equal 'Bearer tok_one'
  end

  it 'throws before exchange code called' do
    # Requesting a token before the code exchange is a wrong call order:
    # the invalid-state RuntimeError, not an SDK error.
    error = assert_raises(RuntimeError) do
      auth.auth_headers
    end
    _(error).must_be_instance_of RuntimeError
    _(error).wont_be_kind_of ::Petstore::Client::Errors::OpenAPIError
  end

  it 'getHost returns configured host' do
    _(auth.host).must_equal 'https://api.example.com'
  end

  # oauth-exchangecode-no-empty-code-guard: an empty/blank authorization
  # code must be rejected before issuing the token POST.
  it 'rejects an empty authorization code' do
    auth.api_client = FakeAuthCodeClient.new([{ status: 200, body: {} }])
    _(-> { auth.exchange_code('') }).must_raise ArgumentError
  end

  it 'rejects a whitespace-only authorization code' do
    auth.api_client = FakeAuthCodeClient.new([{ status: 200, body: {} }])
    _(-> { auth.exchange_code('   ') }).must_raise ArgumentError
  end

  it 'auth_headers_before_exchange_returns_recoverable_error' do
    # Calling auth_headers before exchange_code is a precondition violation.
    # It must surface as a catchable exception so callers can recover --
    # not as a process crash.
    caught = nil
    begin
      auth.auth_headers
    rescue RuntimeError => e
      caught = e
    end
    _(caught).wont_be_nil

    # Caller continues normally after rescuing -- no process crash.
    _(auth.host).must_equal 'https://api.example.com'
  end

  it 'authorize URL with existing query string uses ampersand separator' do
    auth_with_query = Petstore::Client::Auth::OAuth::OAuth2AuthorizationCodeAuthenticator.new(
      'https://api.example.com',
      'my_client_id',
      'my_client_secret',
      'https://x.auth0.com/authorize?audience=api',
      'https://x.auth0.com/oauth/token',
      'https://app.example.com/callback',
      %w[read]
    )

    url = auth_with_query.build_authorization_url
    _(url).must_include 'audience=api'
    _(url).must_include 'response_type=code'
    _(url.count('?')).must_equal 1
  end

  it 'masks the client secret in inspect' do
    # client-secret-leak-in-default-repr: the default Object#inspect dumps
    # every instance variable, leaking @client_secret. The overridden
    # inspect must mask it.
    secret_auth = Petstore::Client::Auth::OAuth::OAuth2AuthorizationCodeAuthenticator.new(
      'https://api.example.com',
      'my_client_id',
      'super_secret_value',
      'https://auth.example.com/authorize',
      'https://auth.example.com/token',
      'https://app.example.com/callback',
      %w[read write]
    )

    _(secret_auth.inspect).wont_include 'super_secret_value'
    _(secret_auth.inspect).must_include '***'
    _(secret_auth.to_s).wont_include 'super_secret_value'
    _(secret_auth.to_s).wont_include 'super_secret_value'
  end

  def test_redacts_secret
    auth = Petstore::Client::Auth::OAuth::OAuth2AuthorizationCodeAuthenticator.new(
      'https://api.example.com',
      'my_client_id',
      'leaky_client_secret',
      'https://auth.example.com/authorize',
      'https://auth.example.com/token',
      'https://app.example.com/callback',
      %w[read write]
    )
    _(auth.inspect).wont_include 'leaky_client_secret'
    _(auth.inspect).must_include '***'
    _(auth.to_s).wont_include 'leaky_client_secret'
    _(auth.to_s).must_include '***'
  end

  it 'sends the code exchange to the token URL and the refresh grant to the refresh URL' do
    client = FakeAuthCodeClient.new([
                                      { status: 200, body: { 'access_token' => 'tok_abc', 'refresh_token' => 'ref_xyz', 'expires_in' => -1 } },
                                      { status: 200, body: { 'access_token' => 'tok_refreshed', 'expires_in' => 3600 } }
                                    ])
    split_auth = Petstore::Client::Auth::OAuth::OAuth2AuthorizationCodeAuthenticator.new(
      'https://api.example.com', 'my_client_id', 'my_client_secret', 'https://auth.example.com/authorize',
      'https://auth.example.com/token', 'https://app.example.com/callback', %w[read],
      refresh_url: 'https://auth.example.com/refresh'
    )
    split_auth.api_client = client

    split_auth.exchange_code('auth_code_123')
    split_auth.auth_headers
    _(client.urls).must_equal ['https://auth.example.com/token', 'https://auth.example.com/refresh']
  end

  it 'keeps ~ literal and percent-encodes * ! \' ( ) in the authorize URL' do
    url = auth.build_authorization_url("state~*!'()")
    _(url).must_include 'state=state~%2A%21%27%28%29'
  end

  it 'keeps ~ literal and percent-encodes * ! \' ( ) in the code exchange body' do
    client = FakeAuthCodeClient.new([
                                      { status: 200, body: { 'access_token' => 'tok_abc', 'expires_in' => 3600 } }
                                    ])
    special_auth = Petstore::Client::Auth::OAuth::OAuth2AuthorizationCodeAuthenticator.new(
      'https://api.example.com', "id~*!'()", "secret~*!'()", 'https://auth.example.com/authorize',
      'https://auth.example.com/token', 'https://app.example.com/callback', %w[read]
    )
    special_auth.api_client = client

    special_auth.exchange_code("code~*!'()")
    _(client.last_body).must_include 'code=code~%2A%21%27%28%29'
    _(client.last_body).must_include 'client_id=id~%2A%21%27%28%29'
    _(client.last_body).must_include 'client_secret=secret~%2A%21%27%28%29'
  end

  it 'shows the host and client id but not the secret in inspect' do
    _(auth.inspect).must_equal(
      "#<#{auth.class.name} host=\"https://api.example.com\" client_id=\"my_client_id\" client_secret=\"***\">"
    )
  end
end
